int kvm_arch_complete_insn_emulated(struct kvm_vcpu *vcpu)
{
    struct kvm_run *run = vcpu->run;
    int ret = 0;

    if (!vcpu->mmio_needed)
        return 0;

    if (vcpu->mmio_is_write) {
        kvm_mmio_write(vcpu, vcpu->mmio_data, vcpu->mmio_size);
        run->exit_reason = KVM_EXIT_MMIO;
        run->mmio.is_write = 1;
        run->mmio.phys_addr = vcpu->mmio_phys_addr;
        run->mmio.len = vcpu->mmio_size;
        ret = 1;
    } else {
        kvm_mmio_read(vcpu, vcpu->mmio_data, vcpu->mmio_size);
        run->exit_reason = KVM_EXIT_MMIO;
        run->mmio.is_write = 0;
        run->mmio.phys_addr = vcpu->mmio_phys_addr;
        run->mmio.len = vcpu->mmio_size;
        ret = 0;
    }

    vcpu->mmio_needed = 0;
    return ret;
}

int kvm_arch_vcpu_ioctl_complete_mmio(struct kvm_vcpu *vcpu) {
    if (!vcpu->mmio_needed)
        return 0;

    if (vcpu->mmio_is_write)
        vcpu->mmio_data = vcpu->arch.mmio_data;
    else
        vcpu->mmio_data = vcpu->arch.mmio_data;

    vcpu->mmio_needed = 0;
    vcpu->run->exit_reason = KVM_EXIT_MMIO;
    vcpu->run->mmio.is_write = vcpu->mmio_is_write;
    vcpu->run->mmio.phys_addr = vcpu->arch.mmio_phys_addr;
    vcpu->run->mmio.len = vcpu->arch.mmio_len;
    if (vcpu->mmio_is_write)
        memcpy(vcpu->run->mmio.data, &vcpu->arch.mmio_data, vcpu->arch.mmio_len);
    else
        memcpy(&vcpu->arch.mmio_data, vcpu->run->mmio.data, vcpu->arch.mmio_len);

    return vcpu->mmio_is_write;
}

int kvm_arch_complete_emulated_mmio(struct kvm_vcpu *vcpu) {
    struct kvm_run *run = vcpu->run;
    int ret = 0;

    if (!vcpu->mmio_needed)
        return 0;

    vcpu->mmio_needed = 0;

    if (vcpu->mmio_is_write)
        ret = 1;

    if (vcpu->mmio_size > 0) {
        if (vcpu->mmio_data) {
            if (vcpu->mmio_is_write)
                kvm_set_user_memory_region(vcpu, vcpu->mmio_phys_addr,
                                           vcpu->mmio_data, vcpu->mmio_size);
            else
                kvm_get_user_memory_region(vcpu, vcpu->mmio_phys_addr,
                                           vcpu->mmio_data, vcpu->mmio_size);
        }

        vcpu->mmio_size = 0;
        vcpu->mmio_phys_addr = 0;
        vcpu->mmio_data = NULL;
    }

    run->exit_reason = KVM_EXIT_MMIO;

    if (vcpu->mmio_is_write)
        run->mmio.is_write = 1;
    else
        run->mmio.is_write = 0;

    run->mmio.phys_addr = vcpu->mmio_phys_addr;
    run->mmio.len = vcpu->mmio_len;
    run->mmio.data = vcpu->mmio_data;

    return ret;
}

int kvm_vcpu_mmio_complete(struct kvm_vcpu *vcpu) {
    struct kvm_run *run = vcpu->run;
    struct kvm_mmio_fragment *frag;

    if (!vcpu->mmio_needed)
        return 0;

    frag = &vcpu->mmio_access;

    if (!frag->len)
        return 0;

    run->exit_reason = KVM_EXIT_MMIO;
    run->mmio.is_write = frag->is_write;
    run->mmio.phys_addr = frag->phys_addr;
    run->mmio.len = frag->len;

    if (frag->is_write) {
        memcpy(run->mmio.data, frag->data, frag->len);
        return 1;
    } else {
        memcpy(frag->data, run->mmio.data, frag->len);
    }

    vcpu->mmio_needed = 0;
    return 0;
}

int kvm_mmio_complete_emulation(struct kvm_vcpu *vcpu) {
    if (!vcpu->mmio_needed)
        return 0;

    vcpu->mmio_needed = 0;
    if (vcpu->mmio_is_write)
        return 1;

    vcpu->arch.complete_userspace_io = NULL;
    kvm_run->exit_reason = KVM_EXIT_MMIO;

    kvm_run->mmio.is_write = vcpu->mmio_is_write;
    kvm_run->mmio.phys_addr = vcpu->mmio_phys_addr;
    kvm_run->mmio.len = vcpu->mmio_len;
    kvm_run->mmio.data = vcpu->mmio_data;

    return 0;
}
